2	//
3	// The `refresh_token` grant (RFC 6749 §6 + DPoP RFC 9449): validate the DPoP proof, look up the
4	// stored refresh token, enforce the client_id match and the DPoP `jkt` binding (a NULL jkt predates
5	// binding enforcement and is rejected), then rotate — consume the old token and mint a fresh
6	// DPoP-bound access token + new refresh token carrying the granted scope forward.
7	
8	use axum::{
9	    http::{HeaderMap, StatusCode},
10	    response::{IntoResponse, Response},
11	    Json,
12	};
13	use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
14	
15	use super::{
16	    cleanup_expired_state, issue_access_token, token_response_headers, TokenRequestForm,
17	    TokenResponse,
18	};
19	use crate::app::AppState;
20	use crate::auth::token::generate_token;
21	use crate::auth::{issue_nonce, validate_dpop_for_token_endpoint, DpopTokenEndpointError};
22	use crate::db::oauth::{
23	    delete_oauth_refresh_token, get_oauth_refresh_token, store_oauth_refresh_token,
24	};
25	use crate::routes::oauth_errors::OAuthTokenError;
26	
27	pub(super) async fn handle_refresh_token(
28	    state: &AppState,
29	    headers: &HeaderMap,
30	    form: TokenRequestForm,
31	) -> Response {
32	    // Prune stale nonces and expired tokens on every request.
33	    cleanup_expired_state(state).await;
34	
35	    // Required fields.
36	    let refresh_token_plaintext = match form.refresh_token.as_deref() {
37	        Some(t) if !t.is_empty() => t.to_string(),
38	        _ => {
39	            return OAuthTokenError::new("invalid_request", "missing parameter: refresh_token")
40	                .into_response();
41	        }
42	    };
43	    let client_id = match form.client_id.as_deref() {
44	        Some(id) if !id.is_empty() => id.to_string(),
45	        _ => {
46	            return OAuthTokenError::new("invalid_request", "missing parameter: client_id")
47	                .into_response();
48	        }
49	    };
50	
51	    // Reject multiple DPoP headers (RFC 9449 §11.1).
52	    if headers.get_all("DPoP").iter().count() > 1 {
53	        return OAuthTokenError::new(
54	            "invalid_dpop_proof",
55	            "multiple DPoP headers are not permitted",
56	        )
57	        .into_response();
58	    }
59	
60	    // Validate DPoP proof — must be present, structurally valid, and carry a valid server nonce.
61	    let dpop_token = match headers.get("DPoP").and_then(|v| v.to_str().ok()) {
62	        Some(t) => t.to_string(),
63	        None => {
64	            return OAuthTokenError::new("invalid_dpop_proof", "DPoP header required")
65	                .into_response();
66	        }
67	    };
68	
69	    let token_url = format!(
70	        "{}/oauth/token",
71	        state.config.public_url.trim_end_matches('/')
72	    );
73	
74	    let jkt =
75	        match validate_dpop_for_token_endpoint(&dpop_token, "POST", &token_url, &state.dpop_nonces)
76	            .await
77	        {
78	            Ok(jkt) => jkt,
79	            Err(DpopTokenEndpointError::MissingHeader) => {
80	                return OAuthTokenError::new("invalid_dpop_proof", "DPoP header required")
81	                    .into_response();
82	            }
83	            Err(DpopTokenEndpointError::InvalidProof(msg)) => {
84	                return OAuthTokenError::new("invalid_dpop_proof", msg).into_response();
85	            }
86	            Err(DpopTokenEndpointError::UseNonce(fresh_nonce)) => {
87	                return OAuthTokenError::with_nonce(
88	                    "use_dpop_nonce",
89	                    "DPoP nonce required",
90	                    fresh_nonce,
91	                )
92	                .into_response();
93	            }
94	        };
95	
96	    // Hash the presented refresh token for DB lookup.
97	    let token_hash = match URL_SAFE_NO_PAD.decode(refresh_token_plaintext.as_str()) {
98	        Ok(bytes) => crate::auth::token::sha256_hex(&bytes),
99	        Err(_) => {
100	            return OAuthTokenError::new("invalid_grant", "refresh token not found or expired")
101	                .into_response();
102	        }
103	    };
104	
105	    // Retrieve the refresh token (without consuming yet).
106	    let stored = match get_oauth_refresh_token(&state.db, &token_hash).await {
107	        Ok(Some(row)) => row,
108	        Ok(None) => {
109	            return OAuthTokenError::new("invalid_grant", "refresh token not found or expired")
110	                .into_response();
111	        }
112	        Err(e) => {
113	            tracing::error!(error = %e, "failed to retrieve refresh token");
114	            return OAuthTokenError::new("server_error", "database error").into_response();
115	        }
116	    };
117	
118	    // Verify client_id matches before consuming.
119	    if stored.client_id != client_id {
120	        return OAuthTokenError::new("invalid_grant", "client_id mismatch").into_response();
121	    }
122	
123	    // DPoP binding check: tokens issued since V012 always carry jkt.
124	    // A NULL jkt means the token predates DPoP binding enforcement — reject it.
125	    match stored.jkt.as_deref() {
126	        None => {
127	            // Refresh tokens issued after V012 always have a jkt. A NULL jkt means
128	            // the token predates DPoP binding enforcement — reject rather than
129	            // silently accepting any key.
130	            return OAuthTokenError::new("invalid_grant", "refresh token not found or expired")
131	                .into_response();
132	        }
133	        Some(stored_jkt) => {
134	            use subtle::ConstantTimeEq;
135	            if !bool::from(stored_jkt.as_bytes().ct_eq(jkt.as_bytes())) {
136	                return OAuthTokenError::new("invalid_grant", "DPoP key mismatch").into_response();
137	            }
138	        }
139	    }
140	
141	    // All validations passed; now consume the token.
142	    if let Err(e) = delete_oauth_refresh_token(&state.db, &token_hash).await {
143	        tracing::error!(error = %e, "failed to delete refresh token");
144	        return OAuthTokenError::new("server_error", "database error").into_response();
145	    }
146	
147	    // Carry the granted granular scope forward across rotation — the rotated
148	    // session grants exactly what the original did. Refresh rows written before
149	    // granular scopes were persisted hold the fixed `com.atproto.refresh` string;
150	    // reusing that verbatim would mint an access token that resolves to
151	    // `AuthScope::Refresh` and fail every access-gated route, so coerce any scope
152	    // that isn't a valid atproto grant to the base `atproto` scope (full access
153	    // under the current session model).
154	    let granted_scope = if crate::auth::oauth_scopes::is_atproto_oauth_scope(&stored.scope) {
155	        stored.scope
156	    } else {
157	        "atproto".to_string()
158	    };
159	
160	    // Issue new ES256 access token.
161	    let access_token = match issue_access_token(
162	        &state.oauth_signing_keypair,
163	        &stored.did,
164	        &granted_scope,
165	        Some(&jkt),
166	        None,
167	        &state.config.public_url,
168	    ) {
169	        Ok(t) => t,
170	        Err(e) => return e.into_response(),
171	    };
172	
173	    // Generate and store new refresh token (rotation: old token already deleted above).
174	    let new_refresh = generate_token();
175	    if let Err(e) = store_oauth_refresh_token(
176	        &state.db,
177	        &new_refresh.hash,
178	        &stored.client_id,
179	        &stored.did,
180	        &granted_scope,
181	        &jkt,
182	    )
183	    .await
184	    {
185	        tracing::error!(error = %e, "failed to store rotated refresh token");
186	        return OAuthTokenError::new("server_error", "database error").into_response();
187	    }
188	
189	    // Issue fresh DPoP nonce for the next request.
190	    let fresh_nonce = issue_nonce(&state.dpop_nonces).await;
191	
192	    let response_headers = match token_response_headers(&fresh_nonce) {
193	        Ok(h) => h,
194	        Err(e) => return e.into_response(),
195	    };
196	
197	    (
198	        StatusCode::OK,
199	        response_headers,
200	        Json(TokenResponse {
201	            access_token,
202	            token_type: "DPoP",
203	            expires_in: 300,
204	            refresh_token: new_refresh.plaintext,
205	            scope: granted_scope,
206	            sub: stored.did,
207	        }),
208	    )
209	        .into_response()
210	}
